High-Level Requirement:
  Summary: Java 11 Precommit failing tasks
  Description: This is the aggregate for all failing tasks in Java 11 Precommit job
Jenkins job 
Groovy script
{code:groovy}
import PrecommitJobBuilder
import CommonJobProperties as properties
PrecommitJobBuilder builder = new PrecommitJobBuilder(
 scope: this,
 nameBase: 'Java11',
 gradleTask: ':javaPreCommit',
 commitTriggering: false,
 gradleSwitches: [
  '-Pdockerfile=Dockerfile-java11',
  '-PdisableSpotlessCheck=true',
  '-PcompileAndRunTestsWithJava11',
  "-Pjava11Home=${properties.JAVA_11_HOME}",
  '--info' // for debug purposes
 ], // spotless checked in separate pre-commit
 triggerPathPatterns: [
 '^model/.*$',
 '^sdks/java/.*$',
 '^runners/.*$',
 '^examples/java/.*$',
 '^examples/kotlin/.*$',
 '^release/.*$',
 ],
 excludePathPatterns: [
 '^sdks/java/extensions/sql/.*$'
 ]
)
builder.build {
 publishers {
 archiveJunit('**/build/test-results/**/*.xml')
 recordIssues {
 tools {
 errorProne()
 java()
 checkStyle {
 pattern('**/build/reports/checkstyle/*.xml')
 }
 configure { node ->
 node / 'spotBugs' << 'io.jenkins.plugins.analysis.warnings.SpotBugs' {
  pattern('**/build/reports/spotbugs/*.xml')
 }
 }
 }
 enabledForFailure(true)
 }
 jacocoCodeCoverage {
 execPattern('**/build/jacoco/*.exec')
 }
 }
}
